(prisma as PrismaClient & { aiGeneration: PrismaClient["aIGeneration"]; aiDraft: PrismaClient["aIDraft"]; aiUsageCounter: PrismaClient["aIUsageCounter"] }).aiGeneration = prisma.aIGeneration;
(prisma as PrismaClient & { aiGeneration: PrismaClient["aIGeneration"]; aiDraft: PrismaClient["aIDraft"]; aiUsageCounter: PrismaClient["aIUsageCounter"] }).aiDraft = prisma.aIDraft;
(prisma as PrismaClient & { aiGeneration: PrismaClient["aIGeneration"]; aiDraft: PrismaClient["aIDraft"]; aiUsageCounter: PrismaClient["aIUsageCounter"] }).aiUsageCounter = prisma.aIUsageCounter;
