const roleSchema = z.enum(["OWNER", "ADMIN", "EDITOR", "VIEWER"]);
const registrationSchema = z.object({ name: z.string().trim().min(2).max(100), email: z.string().trim().email().max(255), password: z.string().min(8).max(128), organizationName: z.string().trim().min(2).max(120).optional() });
const loginSchema = z.object({ email: z.string().trim().email(), password: z.string().min(1).max(128) });
const organizationSchema = z.object({ name: z.string().trim().min(2).max(120) });
const inviteSchema = z.object({ email: z.string().trim().email().max(255), name: z.string().trim().min(2).max(100), role: roleSchema });
const profileSchema = z.object({ name: z.string().trim().min(2).max(100) });
const passwordSchema = z.object({ currentPassword: z.string().min(1).max(128), newPassword: z.string().min(8).max(128) });
const aiGenerationRequestSchema = generationInputSchema.omit({ account: true });
const aiDraftCreateSchema = z.object({ generationId: z.string().cuid(), editedContent: generatedContentSchema.optional() });
const aiDraftUpdateSchema = z.object({ editedContent: generatedContentSchema, status: z.enum(["DRAFT", "ARCHIVED"]).optional() });
const contentTypeSchema = z.enum(["POST", "REEL", "STORY"]);
const contentCreateSchema = z.object({ accountId: z.string().min(1), title: z.string().trim().min(1).max(160), type: contentTypeSchema, caption: z.string().max(2200).nullable().optional(), media: z.record(z.unknown()).nullable().optional(), sourceDraftId: z.string().optional() });
const contentUpdateSchema = z.object({ accountId: z.string().min(1).optional(), title: z.string().trim().min(1).max(160).optional(), type: contentTypeSchema.optional(), caption: z.string().max(2200).nullable().optional(), media: z.record(z.unknown()).nullable().optional() });
const scheduleSchema = z.object({ scheduledFor: z.string().datetime(), timezone: z.string().trim().min(1).max(80).default("UTC") });

function ip(req: Request): string { return req.ip || req.socket.remoteAddress || "unknown"; }
function safeUser(user: { id: string; name: string; email: string; status: string; createdAt: Date; lastLoginAt: Date | null }) { return { id: user.id, name: user.name, email: user.email, status: user.status, createdAt: user.createdAt, lastLoginAt: user.lastLoginAt }; }
async function writeAudit(organizationId: string, actorId: string | null, action: string, req: Request, metadata?: object, resource = "AUTHENTICATION", resourceId?: string, accountId?: string) { await prisma.auditLog.create({ data: { organizationId, actorId, action, resource, resourceId, accountId, metadata: metadata ?? {}, ip: ip(req) } }); }
async function startSession(userId: string, organizationId: string, res: express.Response) { const token = createSessionToken(); await prisma.session.create({ data: { userId, organizationId, tokenHash: hashSessionToken(token), expiresAt: new Date(Date.now() + SESSION_TTL_MS) } }); setSessionCookie(res, token); }
export function publicAccount(account: { id: string; organizationId: string; instagramUserId: string; facebookPageId: string | null; username: string; displayName: string | null; profilePictureUrl: string | null; accountType: string | null; connectedAt: Date | null; lastSyncedAt: Date | null; connectionStatus: string; automationMode: string; tokenExpiresAt: Date | null; lastSyncFailedAt: Date | null; lastSyncError: string | null; lastConnectionError: string | null; followers?: number | null; following?: number | null; mediaCount?: number | null; dataIsMock?: boolean; createdAt: Date; updatedAt: Date }) { return { id: account.id, organizationId: account.organizationId, instagramUserId: account.instagramUserId, facebookPageId: account.facebookPageId, username: account.username, displayName: account.displayName, profilePictureUrl: account.profilePictureUrl, accountType: account.accountType, connectedAt: account.connectedAt, lastSyncedAt: account.lastSyncedAt, connectionStatus: account.connectionStatus, automationMode: account.automationMode, tokenExpiresAt: account.tokenExpiresAt, lastSyncFailedAt: account.lastSyncFailedAt, lastSyncError: account.lastSyncError, lastConnectionError: account.lastConnectionError, followers: account.followers ?? null, following: account.following ?? null, mediaCount: account.mediaCount ?? null, dataIsMock: account.dataIsMock ?? false, createdAt: account.createdAt, updatedAt: account.updatedAt }; }
function webRedirect(params: Record<string, string>): string { const url = new URL(process.env.WEB_APP_URL ?? process.env.WEB_ORIGIN ?? "http://localhost:3000"); url.pathname = "/accounts"; for (const [key, value] of Object.entries(params)) url.searchParams.set(key, value); return url.toString(); }
function aiMonthStart(): Date { const now = new Date(); return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1)); }
function jsonValue(value: unknown): Prisma.InputJsonValue { return value as Prisma.InputJsonValue; }
function aiPromptMetadata(input: z.infer<typeof aiGenerationRequestSchema>): Prisma.InputJsonValue { return jsonValue({ contentType: input.contentType, topic: input.topic, tone: input.tone, audience: input.audience, length: input.length, callToAction: input.callToAction, additionalInstructions: input.additionalInstructions ?? null }); }
function captionFromContent(value: unknown): string | null { if (!value || typeof value !== "object") return null; const item = value as Record<string, unknown>; if (typeof item.caption === "string") return item.caption; if (typeof item.text === "string") return item.text; if (Array.isArray(item.variations) && typeof item.variations[0] === "object" && item.variations[0] && typeof (item.variations[0] as Record<string, unknown>).caption === "string") return (item.variations[0] as Record<string, unknown>).caption as string; return null; }
function contentView(content: any) { const variant = content.variants?.[0]; const scheduled = content.scheduledPosts?.[0] ?? null; return { id: content.id, organizationId: content.organizationId, title: content.title, type: content.type, caption: variant?.caption ?? content.caption ?? null, media: variant?.media ?? null, status: content.status, sourceDraftId: content.sourceDraftId ?? null, account: variant?.account ? { id: variant.account.id, username: variant.account.username, displayName: variant.account.displayName, profilePictureUrl: variant.account.profilePictureUrl } : null, scheduledAt: scheduled?.scheduledFor ?? null, scheduledPost: scheduled ? { id: scheduled.id, status: scheduled.status, scheduledFor: scheduled.scheduledFor, publishedAt: scheduled.publishedAt, externalPostId: scheduled.externalPostId, retryCount: scheduled.retryCount, lastAttemptAt: scheduled.lastAttemptAt, failureReason: scheduled.failureReason } : null, createdAt: content.createdAt, updatedAt: content.updatedAt }; }
function aiDraftContentType(type: string): ContentType { return type === "REEL" ? ContentType.REEL : type === "STORY" ? ContentType.STORY : ContentType.POST; }

app.get("/health", (_req, res) => res.json({ ok: true, service: "social-ops-api" }));

app.post("/api/auth/register", async (req, res) => {
  const limit = authRateLimit(`register:${ip(req)}`); if (!limit.allowed) return res.status(429).json({ error: "RATE_LIMITED", retryAfterSeconds: limit.retryAfterSeconds });
  const parsed = registrationSchema.safeParse(req.body); if (!parsed.success) return res.status(400).json({ error: "VALIDATION_ERROR", details: parsed.error.flatten() });
  const data = parsed.data; const email = data.email.toLowerCase();
  try {
    const passwordHash = await bcrypt.hash(data.password, 12);
    const result = await prisma.$transaction(async (tx) => {
      const existing = await tx.user.findUnique({ where: { email } }); if (existing) throw new Error("EMAIL_TAKEN");
      const user = await tx.user.create({ data: { name: data.name, email, passwordHash, role: Role.OWNER } });
      const organization = await tx.organization.create({ data: { name: data.organizationName ?? `${data.name}'s Workspace` } });
      await tx.organizationMember.create({ data: { organizationId: organization.id, userId: user.id, role: Role.OWNER } });
      await tx.auditLog.create({ data: { organizationId: organization.id, actorId: user.id, action: "REGISTER", resource: "AUTHENTICATION", ip: ip(req), metadata: {} } });
      return { user, organization };
    });
    await startSession(result.user.id, result.organization.id, res); resetAuthRateLimit(`register:${ip(req)}`);
    return res.status(201).json({ user: safeUser(result.user), organization: result.organization });
  } catch (error) { if (error instanceof Error && error.message === "EMAIL_TAKEN") return res.status(409).json({ error: "EMAIL_TAKEN", message: "An account with that email already exists." }); return res.status(500).json({ error: "REGISTRATION_FAILED" }); }
});

app.post("/api/auth/login", async (req, res) => {
  const limit = authRateLimit(`login:${ip(req)}`); if (!limit.allowed) return res.status(429).json({ error: "RATE_LIMITED", retryAfterSeconds: limit.retryAfterSeconds });
  const parsed = loginSchema.safeParse(req.body); if (!parsed.success) return res.status(400).json({ error: "VALIDATION_ERROR", details: parsed.error.flatten() });
  const email = parsed.data.email.toLowerCase(); const user = await prisma.user.findUnique({ where: { email } });
  if (!user || user.status !== "ACTIVE" || !(await bcrypt.compare(parsed.data.password, user.passwordHash))) return res.status(401).json({ error: "INVALID_CREDENTIALS", message: "Email or password is incorrect." });
  const membership = await prisma.organizationMember.findFirst({ where: { userId: user.id }, orderBy: { createdAt: "asc" }, include: { organization: true } });
  if (!membership) return res.status(403).json({ error: "NO_ORGANIZATION", message: "Your account is not assigned to a workspace." });
  await prisma.user.update({ where: { id: user.id }, data: { lastLoginAt: new Date() } }); await startSession(user.id, membership.organizationId, res); resetAuthRateLimit(`login:${ip(req)}`);
  await writeAudit(membership.organizationId, user.id, "LOGIN", req);
  return res.json({ user: safeUser({ ...user, lastLoginAt: new Date() }), organization: membership.organization });
});

app.post("/api/auth/logout", async (req, res) => { const token = req.cookies?.social_ops_session as string | undefined; if (token) { const session = await prisma.session.findFirst({ where: { tokenHash: hashSessionToken(token), revokedAt: null } }); if (session) { await prisma.session.update({ where: { id: session.id }, data: { revokedAt: new Date() } }); await writeAudit(session.organizationId, session.userId, "LOGOUT", req); } } clearSessionCookie(res); return res.status(204).send(); });

const auth = requireAuth(prisma);
app.get("/api/auth/me", auth, async (req, res) => { const user = await prisma.user.findUniqueOrThrow({ where: { id: req.auth!.user.id } }); return res.json({ user: safeUser(user), organization: req.auth!.organization }); });

app.get("/api/organizations", auth, async (req, res) => { const memberships = await prisma.organizationMember.findMany({ where: { userId: req.auth!.user.id }, include: { organization: true }, orderBy: { createdAt: "asc" } }); return res.json({ data: memberships.map((m) => ({ id: m.organization.id, name: m.organization.name, role: m.role })) }); });
app.post("/api/organizations", auth, async (req, res) => { const parsed = organizationSchema.safeParse(req.body); if (!parsed.success) return res.status(400).json({ error: "VALIDATION_ERROR", details: parsed.error.flatten() }); const organization = await prisma.organization.create({ data: { name: parsed.data.name } }); await prisma.organizationMember.create({ data: { organizationId: organization.id, userId: req.auth!.user.id, role: Role.OWNER } }); await prisma.session.update({ where: { id: req.auth!.sessionId }, data: { organizationId: organization.id } }); await writeAudit(organization.id, req.auth!.user.id, "ORGANIZATION_CREATED", req); return res.status(201).json({ organization, role: Role.OWNER }); });
app.post("/api/organizations/:organizationId/select", auth, async (req, res) => { const organizationId = String(req.params.organizationId); const membership = await prisma.organizationMember.findUnique({ where: { organizationId_userId: { organizationId, userId: req.auth!.user.id } } }); if (!membership) return res.status(403).json({ error: "ORGANIZATION_ACCESS_DENIED" }); const organization = await prisma.organization.findUniqueOrThrow({ where: { id: organizationId } }); await prisma.session.update({ where: { id: req.auth!.sessionId }, data: { organizationId: membership.organizationId } }); return res.json({ organization, role: membership.role }); });

app.get("/api/team", auth, async (req, res) => { const members = await prisma.organizationMember.findMany({ where: { organizationId: req.auth!.organization.id }, include: { user: true }, orderBy: { createdAt: "asc" } }); const invitations = await prisma.invitation.findMany({ where: { organizationId: req.auth!.organization.id, acceptedAt: null, expiresAt: { gt: new Date() } }, orderBy: { createdAt: "desc" } }); return res.json({ data: members.map((m) => ({ id: m.user.id, name: m.user.name, email: m.user.email, role: m.role, status: m.user.status, joinedAt: m.createdAt })), invitations: invitations.map((i) => ({ id: i.id, email: i.email, name: i.name, role: i.role, status: "INVITED", invitedAt: i.createdAt })) }); });
app.post("/api/team/invite", auth, requireRole("OWNER", "ADMIN"), async (req, res) => { const parsed = inviteSchema.safeParse(req.body); if (!parsed.success) return res.status(400).json({ error: "VALIDATION_ERROR", details: parsed.error.flatten() }); if (!canManageRole(req.auth!.organization.role, parsed.data.role)) return res.status(403).json({ error: "FORBIDDEN", message: "You cannot invite a member with that role." }); const email = parsed.data.email.toLowerCase(); const existingUser = await prisma.user.findUnique({ where: { email } }); if (existingUser && await prisma.organizationMember.findUnique({ where: { organizationId_userId: { organizationId: req.auth!.organization.id, userId: existingUser.id } } })) return res.status(409).json({ error: "ALREADY_MEMBER" }); const rawToken = randomInvitationToken(); const invitation = await prisma.invitation.create({ data: { organizationId: req.auth!.organization.id, invitedById: req.auth!.user.id, email, name: parsed.data.name, role: parsed.data.role, tokenHash: hashInvitationToken(rawToken), expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000) } }); await writeAudit(req.auth!.organization.id, req.auth!.user.id, "USER_INVITED", req, { email, role: parsed.data.role }); return res.status(201).json({ invitation: { id: invitation.id, email: invitation.email, role: invitation.role, expiresAt: invitation.expiresAt }, inviteToken: process.env.NODE_ENV === "production" ? undefined : rawToken }); });
app.post("/api/team/invitations/accept", async (req, res) => { const parsed = z.object({ token: z.string().min(20), password: z.string().min(8).max(128) }).safeParse(req.body); if (!parsed.success) return res.status(400).json({ error: "VALIDATION_ERROR", details: parsed.error.flatten() }); const invitation = await prisma.invitation.findFirst({ where: { tokenHash: hashInvitationToken(parsed.data.token), acceptedAt: null, expiresAt: { gt: new Date() } } }); if (!invitation) return res.status(400).json({ error: "INVITATION_INVALID" }); const passwordHash = await bcrypt.hash(parsed.data.password, 12); const result = await prisma.$transaction(async (tx) => { const existing = await tx.user.findUnique({ where: { email: invitation.email } }); const user = existing ?? await tx.user.create({ data: { name: invitation.name, email: invitation.email, passwordHash, role: Role.VIEWER } }); if (existing) await tx.user.update({ where: { id: existing.id }, data: { passwordHash, status: "ACTIVE" } }); await tx.organizationMember.create({ data: { organizationId: invitation.organizationId, userId: user.id, role: invitation.role } }); await tx.invitation.update({ where: { id: invitation.id }, data: { acceptedAt: new Date() } }); await tx.auditLog.create({ data: { organizationId: invitation.organizationId, actorId: user.id, action: "INVITATION_ACCEPTED", resource: "TEAM", resourceId: user.id, metadata: {} } }); return { user }; }); await startSession(result.user.id, invitation.organizationId, res); return res.status(201).json({ user: safeUser({ ...result.user, createdAt: result.user.createdAt, lastLoginAt: result.user.lastLoginAt }), organizationId: invitation.organizationId }); });
app.patch("/api/team/:userId", auth, requireRole("OWNER", "ADMIN"), async (req, res) => { const parsed = z.object({ role: roleSchema }).safeParse(req.body); if (!parsed.success) return res.status(400).json({ error: "VALIDATION_ERROR", details: parsed.error.flatten() }); if (!canManageRole(req.auth!.organization.role, parsed.data.role)) return res.status(403).json({ error: "FORBIDDEN" }); const userId = String(req.params.userId); const target = await prisma.organizationMember.findUnique({ where: { organizationId_userId: { organizationId: req.auth!.organization.id, userId } } }); if (!target) return res.status(404).json({ error: "MEMBER_NOT_FOUND" }); if (target.role === "OWNER" && parsed.data.role !== "OWNER") { const owners = await prisma.organizationMember.count({ where: { organizationId: target.organizationId, role: "OWNER" } }); if (owners <= 1) return res.status(400).json({ error: "LAST_OWNER" }); } const updated = await prisma.organizationMember.update({ where: { id: target.id }, data: { role: parsed.data.role } }); await writeAudit(req.auth!.organization.id, req.auth!.user.id, "ROLE_CHANGED", req, { targetUserId: userId, role: parsed.data.role }); return res.json({ role: updated.role }); });
app.delete("/api/team/:userId", auth, requireRole("OWNER", "ADMIN"), async (req, res) => { const userId = String(req.params.userId); const target = await prisma.organizationMember.findUnique({ where: { organizationId_userId: { organizationId: req.auth!.organization.id, userId } } }); if (!target) return res.status(404).json({ error: "MEMBER_NOT_FOUND" }); if (!canManageRole(req.auth!.organization.role, target.role) || target.userId === req.auth!.user.id) return res.status(403).json({ error: "FORBIDDEN" }); if (target.role === "OWNER" && await prisma.organizationMember.count({ where: { organizationId: target.organizationId, role: "OWNER" } }) <= 1) return res.status(400).json({ error: "LAST_OWNER" }); await prisma.organizationMember.delete({ where: { id: target.id } }); await writeAudit(req.auth!.organization.id, req.auth!.user.id, "MEMBER_REMOVED", req, { targetUserId: userId }); return res.status(204).send(); });

app.get("/api/account/profile", auth, async (req, res) => { const user = await prisma.user.findUniqueOrThrow({ where: { id: req.auth!.user.id } }); return res.json({ user: safeUser(user) }); });
app.patch("/api/account/profile", auth, async (req, res) => { const parsed = profileSchema.safeParse(req.body); if (!parsed.success) return res.status(400).json({ error: "VALIDATION_ERROR", details: parsed.error.flatten() }); const user = await prisma.user.update({ where: { id: req.auth!.user.id }, data: { name: parsed.data.name } }); await writeAudit(req.auth!.organization.id, req.auth!.user.id, "PROFILE_UPDATED", req); return res.json({ user: safeUser(user) }); });
app.patch("/api/account/password", auth, async (req, res) => { const parsed = passwordSchema.safeParse(req.body); if (!parsed.success) return res.status(400).json({ error: "VALIDATION_ERROR", details: parsed.error.flatten() }); const user = await prisma.user.findUniqueOrThrow({ where: { id: req.auth!.user.id } }); if (!(await bcrypt.compare(parsed.data.currentPassword, user.passwordHash))) return res.status(400).json({ error: "CURRENT_PASSWORD_INVALID" }); await prisma.user.update({ where: { id: user.id }, data: { passwordHash: await bcrypt.hash(parsed.data.newPassword, 12) } }); await writeAudit(req.auth!.organization.id, req.auth!.user.id, "PASSWORD_CHANGED", req); return res.status(204).send(); });

async function findAIAccount(accountId: string, organizationId: string) { return prisma.instagramAccount.findFirst({ where: { id: accountId, organizationId }, select: { id: true, username: true, displayName: true, accountType: true, dataIsMock: true } }); }
async function writeAIGenerationFailure(accountId: string, input: z.infer<typeof aiGenerationRequestSchema>, provider: { name: string; modelId: string }, error: unknown, req: Request) {
  const generation = await prisma.aiGeneration.create({ data: { organizationId: req.auth!.organization.id, createdById: req.auth!.user.id, instagramAccountId: accountId, contentType: input.contentType, provider: provider.name, modelId: provider.modelId, status: AIGenerationStatus.FAILED, promptMetadata: aiPromptMetadata(input), error: error instanceof Error ? error.message.slice(0, 240) : "AI_GENERATION_FAILED" } });
  await writeAudit(req.auth!.organization.id, req.auth!.user.id, "AI_GENERATION_FAILED", req, { generationId: generation.id, contentType: input.contentType, provider: provider.name }, "AI_GENERATION", generation.id, accountId);
  return generation;
}
app.post("/api/ai/generate", auth, requireRole("OWNER", "ADMIN", "EDITOR"), async (req, res) => {
  const limit = authRateLimit(`ai-generate:${req.auth!.organization.id}:${req.auth!.user.id}`); if (!limit.allowed) return res.status(429).json({ error: "RATE_LIMITED", retryAfterSeconds: limit.retryAfterSeconds });
  const parsed = aiGenerationRequestSchema.safeParse(req.body); if (!parsed.success) return res.status(400).json({ error: "VALIDATION_ERROR", details: parsed.error.flatten() });
  const account = await findAIAccount(String(req.body?.accountId ?? ""), req.auth!.organization.id); if (!account) return res.status(404).json({ error: "ACCOUNT_NOT_FOUND" });
  const provider = createAIProvider(); const input = { ...parsed.data, account };
  await prisma.aiUsageCounter.upsert({ where: { organizationId_periodStart: { organizationId: req.auth!.organization.id, periodStart: aiMonthStart() } }, update: { generationCount: { increment: 1 } }, create: { organizationId: req.auth!.organization.id, periodStart: aiMonthStart(), generationCount: 1 } });
  try {
    const result = await provider.generate(input); const generation = await prisma.aiGeneration.create({ data: { organizationId: req.auth!.organization.id, createdById: req.auth!.user.id, instagramAccountId: account.id, contentType: input.contentType, provider: provider.name, modelId: provider.modelId, status: AIGenerationStatus.SUCCEEDED, promptMetadata: aiPromptMetadata(parsed.data), result: jsonValue(result) } });
    await writeAudit(req.auth!.organization.id, req.auth!.user.id, "AI_GENERATION", req, { generationId: generation.id, contentType: input.contentType, provider: provider.name }, "AI_GENERATION", generation.id, account.id);
    return res.status(201).json({ generation: { id: generation.id, contentType: generation.contentType, provider: generation.provider, modelId: generation.modelId, createdAt: generation.createdAt }, content: result, account, usage: { monthStart: aiMonthStart(), generationCount: (await prisma.aiUsageCounter.findUnique({ where: { organizationId_periodStart: { organizationId: req.auth!.organization.id, periodStart: aiMonthStart() } }, select: { generationCount: true } }))?.generationCount ?? 1 } });
  } catch (error) { const generation = await writeAIGenerationFailure(account.id, parsed.data, provider, error, req); return res.status(502).json({ error: "AI_GENERATION_FAILED", message: "The content provider could not generate content. Try again.", generationId: generation.id }); }
});

