app.get("/api/dashboard", auth, async (req, res) => {
  const organizationId = req.auth!.organization.id;
  const [accounts, contentByStatus, scheduledByStatus, aiGenerations, recentContent, activity] = await Promise.all([
    prisma.instagramAccount.findMany({ where: { organizationId }, orderBy: { username: "asc" } }),
    prisma.content.groupBy({ by: ["status"], where: { organizationId }, _count: { _all: true } }),
    prisma.scheduledPost.groupBy({ by: ["status"], where: { content: { organizationId } }, _count: { _all: true } }),
    prisma.aiGeneration.count({ where: { organizationId } }),
    prisma.content.findMany({ where: { organizationId }, include: { variants: { include: { account: true } }, scheduledPosts: { orderBy: { scheduledFor: "desc" }, take: 1 } }, orderBy: { updatedAt: "desc" }, take: 8 }),
    prisma.auditLog.findMany({ where: { organizationId }, include: { actor: { select: { name: true, email: true } }, account: { select: { username: true } } }, orderBy: { createdAt: "desc" }, take: 8 }),
  ]);
  const counts = Object.fromEntries(contentByStatus.map((row) => [row.status, row._count._all]));
  const jobCounts = Object.fromEntries(scheduledByStatus.map((row) => [row.status, row._count._all]));
  return res.json({ accounts: accounts.map(publicAccount), metrics: { connectedAccounts: accounts.filter((account) => account.connectionStatus === "CONNECTED").length, contentCreated: await prisma.content.count({ where: { organizationId } }), scheduledContent: (jobCounts.QUEUED ?? 0) + (jobCounts.PUBLISHING ?? 0), publishedContent: counts.PUBLISHED ?? 0, failedPublishingJobs: jobCounts.FAILED ?? 0, aiGenerations }, contentCounts: counts, recentContent: recentContent.map(contentView), activity: activity.map((row) => ({ id: row.id, action: row.action, resource: row.resource, resourceId: row.resourceId, metadata: row.metadata, createdAt: row.createdAt, actor: row.actor, account: row.account })) });
});

