async function createPublishingSchedule(req: Request, res: express.Response, contentId: string, scheduledFor: Date, timezone: string) { const content = await prisma.content.findFirst({ where: { id: contentId, organizationId: req.auth!.organization.id }, include: { variants: true, scheduledPosts: { where: { status: { in: [JobStatus.QUEUED, JobStatus.PUBLISHING] } }, take: 1 } } }); if (!content) return res.status(404).json({ error: "CONTENT_NOT_FOUND" }); const variant = content.variants[0]; if (!variant) return res.status(400).json({ error: "CONTENT_ACCOUNT_REQUIRED" }); if (content.scheduledPosts.length) await prisma.scheduledPost.update({ where: { id: content.scheduledPosts[0].id }, data: { status: JobStatus.CANCELED } }); const post = await prisma.scheduledPost.create({ data: { contentId: content.id, instagramAccountId: variant.instagramAccountId, scheduledFor, timezone, status: JobStatus.QUEUED, idempotencyKey: `${content.id}:${scheduledFor.toISOString()}:${Date.now()}` } }); const jobId = await enqueuePublishing(prisma, post.id, req.auth!.organization.id, req.auth!.user.id, Math.max(0, scheduledFor.getTime() - Date.now())); await prisma.content.update({ where: { id: content.id }, data: { status: scheduledFor.getTime() > Date.now() ? ContentStatus.SCHEDULED : ContentStatus.PUBLISHING } }); await writeAudit(req.auth!.organization.id, req.auth!.user.id, scheduledFor.getTime() > Date.now() ? "CONTENT_SCHEDULED" : "PUBLISH_REQUESTED", req, { contentId: content.id, scheduledPostId: post.id, jobId }, "CONTENT", content.id, variant.instagramAccountId); return res.status(202).json({ scheduledPost: { ...post, bullmqJobId: jobId } }); }
