function analyticsRange(query: Request["query"]): { from: Date; to: Date } { const to = query.to ? new Date(String(query.to)) : new Date(); const from = query.from ? new Date(String(query.from)) : new Date(to.getTime() - 30 * 86400000); if (Number.isNaN(from.getTime()) || Number.isNaN(to.getTime()) || from > to) throw new Error("INVALID_DATE_RANGE"); return { from, to }; }
